export const KANTO_SETS_MAP = new Map(KANTO_POKEMON_LIST.map(p => [p.id, p.set]));
export const KANTO_SETS_BY_NAME = new Map(KANTO_POKEMON_LIST.map(p => [p.name.toLowerCase().replace(/[^a-z0-9]/g, ""), p.set]));

export function getKantoStarterSet(speciesOrId) {
  const key = String(speciesOrId || "").toLowerCase().replace(/[^a-z0-9]/g, "");
  const set = KANTO_SETS_MAP.get(key) || KANTO_SETS_BY_NAME.get(key);
  return set ? structuredClone(set) : null;
}
